<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class ClientCareService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    public function clientSite(mixed $id): array {$site=$this->access->requireSite($id);if(!$this->db->fetch('SELECT client_id FROM client_portal_access WHERE company_id=:company AND user_id=:actor AND client_id=:client',['company'=>$this->company(),'actor'=>$this->actor(),'client'=>$site['client_id']]))throw HttpException::notFound();return $site;}
    public function clientSites(): array {$rows=$this->db->fetchAll('SELECT DISTINCT s.site_id,s.site_name,s.client_id FROM sites s JOIN client_portal_access a ON a.company_id=s.company_id AND a.client_id=s.client_id WHERE s.company_id=:company AND a.user_id=:actor AND s.deleted_at IS NULL ORDER BY s.site_name LIMIT 500',['company'=>$this->company(),'actor'=>$this->actor()]);return array_values(array_filter($rows,fn($r)=>$this->access->allowed($r['site_id'])));}
    public function requests(array $input,bool $client=false): array {
        $this->fields($input,['site_id']);$site=$client?$this->clientSite($input['site_id']??null):$this->access->requireSite($input['site_id']??null);$rows=$this->db->fetchAll('SELECT request_id,site_id,request_type,title,description,state,revision,related_report_id,created_at,response_due_at,first_response_at,resolved_at,confirmed_at FROM client_requests WHERE company_id=:company AND site_id=:site AND client_id=:client ORDER BY request_id DESC LIMIT 300',['company'=>$this->company(),'site'=>$site['site_id'],'client'=>$site['client_id']]);foreach($rows as&$r)$r['response_overdue']=$r['first_response_at']===null&&$r['response_due_at']<gmdate('Y-m-d H:i:s');unset($r);return $rows;
    }
    private function event(string $id,string $type,string $audience,string $message,bool $client): void {$this->db->execute('INSERT INTO client_request_events(company_id,request_id,event_type,audience,message,actor_user_id,actor_kind,occurred_at) VALUES(:company,:request,:type,:audience,:message,:actor,:kind,:now)',['company'=>$this->company(),'request'=>$id,'type'=>$type,'audience'=>$audience,'message'=>$message,'actor'=>$this->actor(),'kind'=>$client?'CLIENT':'COMPANY','now'=>gmdate('Y-m-d H:i:s')]);}
    public function create(array $input,bool $client=false): array {return $this->atomic(function()use($input,$client){
        $this->fields($input,['site_id','request_type','title','description','related_report_id']);$site=$client?$this->clientSite($input['site_id']??null):$this->access->requireSite($input['site_id']??null);$type=$input['request_type']??null;if(!in_array($type,['REQUEST','COMPLAINT','REPORT_QUESTION'],true))throw HttpException::unprocessable('Choose a request, complaint or report question.');$report=null;if(isset($input['related_report_id'])&&$input['related_report_id']!==''){$report=$this->row('published_site_reports','report_id',$input['related_report_id']);if((string)$report['site_id']!==(string)$site['site_id']||(string)$report['client_id']!==(string)$site['client_id'])throw HttpException::notFound('Report not found for this client site.');}if($type==='REPORT_QUESTION'&&!$report)throw HttpException::unprocessable('Choose the report for this question.');
        $description=$this->text($input['description']??null,6000);$this->db->execute('INSERT INTO client_requests(company_id,client_id,site_id,request_type,title,description,related_report_id,created_by_user_id,created_at,response_due_at) VALUES(:company,:client,:site,:type,:title,:description,:report,:actor,:now,:due)',['company'=>$this->company(),'client'=>$site['client_id'],'site'=>$site['site_id'],'type'=>$type,'title'=>$this->text($input['title']??null,150),'description'=>$description,'report'=>$report['report_id']??null,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'due'=>gmdate('Y-m-d H:i:s',time()+86400)]);$created=$this->created('client_request');$this->event($created['id'],'CREATED','CLIENT',$description,$client);return $created;
    });}
    private function requestRow(string $id,bool $client): array {$row=$this->row('client_requests','request_id',$id);$site=$client?$this->clientSite($row['site_id']):$this->access->requireSite($row['site_id']);if((string)$site['client_id']!==(string)$row['client_id'])throw HttpException::notFound();return $row;}
    public function history(string $id,bool $client=false): array {$this->requestRow($id,$client);return $this->db->fetchAll('SELECT event_type,audience,message,actor_kind,occurred_at FROM client_request_events WHERE company_id=:company AND request_id=:id'.($client?" AND audience='CLIENT'":'').' ORDER BY event_id',['company'=>$this->company(),'id'=>$id]);}
    public function action(string $id,string $action,array $input,bool $client=false): array {return $this->atomic(function()use($id,$action,$input,$client){
        $this->fields($input,$client?['expected_revision','message']:['expected_revision','message','audience']);$row=$this->requestRow($id,$client);if($this->number($input['expected_revision']??null)!==(int)$row['revision'])throw HttpException::conflict('The request changed. Refresh before replying or confirming.');$message=$this->text($input['message']??null,4000);$state=$row['state'];$audience=$client?'CLIENT':($input['audience']??'CLIENT');if(!in_array($audience,['CLIENT','INTERNAL'],true))throw HttpException::unprocessable('Invalid message audience.');$resolved=$row['resolved_at'];$confirmed=null;$confirmer=null;
        if($client){
            if($action==='confirm'&&$state==='RESOLVED'){$state='CLOSED';$confirmed=gmdate('Y-m-d H:i:s');$confirmer=$this->actor();}
            elseif($action==='reopen'&&$state==='RESOLVED'){$state='OPEN';$resolved=null;}
            elseif($action!=='reply'||$state==='CLOSED')throw HttpException::conflict('This client action is not available in the current state.');
        }else{
            if($action==='begin'&&$state==='OPEN')$state='IN_PROGRESS';elseif($action==='resolve'&&in_array($state,['OPEN','IN_PROGRESS'],true)){$state='RESOLVED';$resolved=gmdate('Y-m-d H:i:s');if($audience!=='CLIENT')throw HttpException::unprocessable('Resolution must be visible to the client.');}elseif($action!=='reply'||$state==='CLOSED')throw HttpException::conflict('Only the client can confirm resolution; invalid company action.');
        }
        $this->db->execute('UPDATE client_requests SET first_response_at=:first,state=:state,revision=revision+1,resolved_at=:resolved,confirmed_at=:confirmed,confirmed_by_user_id=:confirmer WHERE company_id=:company AND request_id=:id',['first'=>$row['first_response_at']??(!$client&&$audience==='CLIENT'?gmdate('Y-m-d H:i:s'):null),'state'=>$state,'resolved'=>$resolved,'confirmed'=>$confirmed,'confirmer'=>$confirmer,'company'=>$this->company(),'id'=>$id]);$this->event($id,strtoupper($action),$audience,$message,$client);$this->audit->record('client_request',$action,$id);return ['state'=>$state,'revision'=>(int)$row['revision']+1];
    });}
    public static function reportHash(array $report): string {return hash('sha256',json_encode(array_map(static fn($k)=>(string)($report[$k]??''),['report_id','client_id','site_id','title','report_text','published_at']),JSON_THROW_ON_ERROR));}
    public function reportsForReview(): array {
        $reports=$this->db->fetchAll('SELECT DISTINCT r.* FROM published_site_reports r JOIN client_portal_access a ON a.company_id=r.company_id AND a.client_id=r.client_id JOIN sites s ON s.company_id=r.company_id AND s.site_id=r.site_id AND s.client_id=r.client_id WHERE r.company_id=:company AND a.user_id=:actor AND s.deleted_at IS NULL ORDER BY r.report_id DESC LIMIT 200',['company'=>$this->company(),'actor'=>$this->actor()]);$out=[];foreach($reports as$r){if(!$this->access->allowed($r['site_id']))continue;$hash=self::reportHash($r);$r['report_hash']=$hash;$r['my_acknowledgement']=$this->db->fetch('SELECT acknowledged_at FROM client_report_reviews WHERE company_id=:company AND report_id=:report AND user_id=:actor AND report_hash=:hash',['company'=>$this->company(),'report'=>$r['report_id'],'actor'=>$this->actor(),'hash'=>$hash]);$out[]=$r;}return $out;
    }
    public function acknowledge(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_hash']);$report=$this->row('published_site_reports','report_id',$id);$site=$this->clientSite($report['site_id']);if((string)$site['client_id']!==(string)$report['client_id'])throw HttpException::notFound();$hash=self::reportHash($report);if(!is_string($input['expected_hash']??null)||!hash_equals($hash,$input['expected_hash']))throw HttpException::conflict('Report content changed. Read the current report before acknowledging.');$keys=['company'=>$this->company(),'report'=>$id,'actor'=>$this->actor(),'hash'=>$hash];if(!$this->db->fetch('SELECT review_id FROM client_report_reviews WHERE company_id=:company AND report_id=:report AND user_id=:actor AND report_hash=:hash',$keys))$this->db->execute('INSERT INTO client_report_reviews(company_id,report_id,user_id,report_hash,acknowledged_at) VALUES(:company,:report,:actor,:hash,:now)',$keys+['now'=>gmdate('Y-m-d H:i:s')]);$this->audit->record('client_report','explicitly_acknowledged',$id);return ['acknowledged'=>true,'report_hash'=>$hash];});}
    public function reviews(array $input): array {$this->fields($input,['site_id']);$site=$this->access->requireSite($input['site_id']??null);$rows=$this->db->fetchAll('SELECT a.report_id,a.user_id,a.report_hash,a.acknowledged_at,r.client_id,r.site_id,r.title,r.report_text,r.published_at FROM client_report_reviews a JOIN published_site_reports r ON r.company_id=a.company_id AND r.report_id=a.report_id WHERE a.company_id=:company AND r.site_id=:site ORDER BY a.review_id DESC LIMIT 500',['company'=>$this->company(),'site'=>$site['site_id']]);foreach($rows as&$r){$r['matches_current_report']=hash_equals($r['report_hash'],self::reportHash($r));unset($r['report_text']);}unset($r);return $rows;}
}
